function Dashboard({ budget, items, goals, onNavigate, onLoadDemo, onReset }: { budget: BudgetSettings; items: ShoppingItem[]; goals: SavingsGoal[]; onNavigate: (path: string) => void; onLoadDemo: () => void; onReset: () => void }) {
  const planned = items.filter((item) => !item.purchased).reduce((sum, item) => sum + item.estimatedPrice * item.quantity, 0);
  const purchased = items.filter((item) => item.purchased).reduce((sum, item) => sum + (item.actualPrice || item.estimatedPrice) * item.quantity, 0);
  const needs = items.filter((item) => item.needWant === 'Need').reduce((sum, item) => sum + item.estimatedPrice * item.quantity, 0);
  const remaining = budget.shoppingBudget - planned - purchased;
  const potentialSavings = items.filter((item) => item.needWant === 'Want' && item.priority === 'Low').reduce((sum, item) => sum + item.estimatedPrice * item.quantity, 0);
  const usedPercent = Math.round(((planned + purchased) / Math.max(1, budget.shoppingBudget)) * 100);
  const health = Math.round(Math.min(100, Math.max(0, 55 + ((budget.shoppingBudget - planned) / Math.max(1, budget.shoppingBudget)) * 25 + (needs / Math.max(1, planned)) * 20)));
  const healthTone = health >= 75 ? 'teal' : health >= 50 ? 'gold' : 'coral';
  const healthLabel = health >= 75 ? 'Healthy' : health >= 50 ? 'Caution' : 'Over budget';
  return <div className="space-y-7">
    <div className="relative overflow-hidden rounded-[24px] bg-[#173c40] px-6 py-7 text-[#f7f1df] shadow-[0_18px_45px_rgba(23,60,64,.18)] sm:px-9 sm:py-9">
      <div className="absolute -right-10 -top-16 h-64 w-64 rounded-full border-[34px] border-[#e8806d]/25" /><div className="absolute -bottom-20 right-24 h-48 w-48 rounded-full border-[22px] border-[#e8bd5b]/20" />
      <div className="relative max-w-2xl"><div className="eyebrow mb-3 text-[#a9cbc2]">Pathway A – Continuation Track · demonstration workspace</div><div className="mb-4 font-mono text-xs tracking-[.08em] text-[#e8bd5b]">Plan Smarter. Spend Better. Save More.</div><h1 className="font-display text-4xl font-bold tracking-[-.045em] sm:text-5xl">Good Evening — Let’s make today’s shopping smarter.</h1><p className="mt-4 max-w-xl text-sm leading-6 text-[#c8d9d0]">An intelligent decision-support prototype for everyday budget-conscious shopping.</p><div className="mt-7 flex flex-wrap gap-3"><Button onClick={() => onNavigate('/shopping-list')} variant="primary" className="bg-[#e8806d] text-[#fff7ea] hover:bg-[#ef927f]"><Plus size={16} /> Add to shopping list</Button><Button onClick={() => onNavigate('/what-if')} variant="outline" className="border-[#71968d] bg-transparent !text-[#f7f1df] hover:bg-[#2b5556]"><Calculator size={16} /> Run a what-if</Button><Button onClick={onLoadDemo} variant="outline" className="border-[#71968d] bg-transparent !text-[#f7f1df] hover:bg-[#2b5556]"><ShoppingBasket size={16} /> Load demo data</Button><Button onClick={() => { if (window.confirm('Reset all local prototype data?')) onReset(); }} variant="outline" className="border-[#71968d] bg-transparent !text-[#f7f1df] hover:bg-[#2b5556]"><RotateCcw size={16} /> Reset demo data</Button></div></div>
    </div>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <StatCard label="Monthly budget" value={money(budget.shoppingBudget)} detail="your current shopping boundary" icon={CircleDollarSign} tone="blue" />
      <StatCard label="Planned spending" value={money(planned)} detail={`${items.filter((i) => !i.purchased).length} items still planned`} icon={ShoppingBasket} tone="teal" />
      <StatCard label="Actual spending" value={money(purchased)} detail={`${items.filter((i) => i.purchased).length} items marked purchased`} icon={Check} tone="gold" />
      <StatCard label="Remaining budget" value={money(Math.max(0, remaining))} detail={remaining >= 0 ? 'room left after the current plan' : 'over the current shopping boundary'} icon={CircleDollarSign} tone={remaining >= 0 ? 'teal' : 'coral'} trend={remaining >= 0 ? 'up' : 'down'} />
      <StatCard label="Potential savings" value={money(potentialSavings)} detail="low-priority Want items you could postpone" icon={TrendingDown} tone="gold" />
      <StatCard label="Budget used" value={`${Math.max(0, usedPercent)}%`} detail="planned plus actual against boundary" icon={BarChart3} tone="blue" />
      <StatCard label="Budget health score" value={`${health}/100`} detail={`${healthLabel} · calculated from current data`} icon={Gauge} tone={healthTone} trend={health >= 75 ? 'up' : 'down'} />
    </div>
    <div className="grid gap-5 lg:grid-cols-[1.4fr_.8fr]">
      <div className="surface rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">Next decision</div><h2 className="mt-1 font-display text-xl font-bold">Keep the essentials moving</h2></div><Button variant="quiet" onClick={() => onNavigate('/need-vs-want')}>Review list <ArrowRight size={15} /></Button></div>
        <div className="space-y-4">{items.filter((item) => !item.purchased).slice(0, 3).map((item) => <div key={item.id} className="flex items-center gap-3 rounded-xl bg-background/65 p-3" data-testid={`row-next-item-${item.id}`}><div className={`grid h-9 w-9 place-items-center rounded-lg ${item.needWant === 'Need' ? 'bg-primary/10 text-primary' : 'bg-accent/10 text-[#b84b3c]'}`}><ShoppingBasket size={16} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{item.name}</div><div className="mt-0.5 text-xs text-muted-foreground">{item.category} · {item.store}</div></div><Tag tone={item.needWant === 'Need' ? 'teal' : 'coral'}>{item.needWant}</Tag><span className="font-mono text-sm">{money(item.estimatedPrice * item.quantity)}</span></div>)}</div>
      </div>
      <div className="surface rounded-2xl p-5 sm:p-6"><div className="eyebrow">Savings in motion</div><h2 className="mt-1 font-display text-xl font-bold">Two reasons to keep going</h2><div className="mt-5 space-y-5">{goals.map((goal) => <div key={goal.id}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{goal.name}</span><span className="font-mono text-xs text-muted-foreground">{money(goal.saved)} / {money(goal.target)}</span></div><Progress value={(goal.saved / goal.target) * 100} color="bg-[#e8bd5b]" /><div className="mt-2 text-xs text-muted-foreground">{Math.round((goal.saved / goal.target) * 100)}% · target {new Date(goal.targetDate).toLocaleDateString('en-IE', { month: 'short', year: 'numeric' })}</div></div>)}</div><Button variant="outline" className="mt-6 w-full" onClick={() => onNavigate('/savings-goals')}>Open savings goals</Button></div>
    </div>
    <div className="flex items-start gap-3 rounded-2xl border border-[#e8bd5b]/40 bg-[#fff5d9] p-4 text-[#6f581e]"><Info size={18} className="mt-0.5 shrink-0" /><div><div className="text-sm font-bold">DEMONSTRATION DATA — NOT REAL USER VALIDATION</div><p className="mt-1 text-xs leading-5">This prototype uses sample figures saved in your browser. Price rows are illustrative, not live prices, and no recommendation is financial advice.</p></div></div>
  </div>;
}

function ShoppingList({ items, setItems }: { items: ShoppingItem[]; setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>> }) {
  const [adding, setAdding] = useState(false);
  const [filter, setFilter] = useState<'All' | NeedWant>('All');
  const [draft, setDraft] = useState({ name: '', category: 'Groceries', quantity: '1', price: '', needWant: 'Need' as NeedWant, priority: 'Medium' as Priority, store: '' });
  const visible = items.filter((item) => filter === 'All' || item.needWant === filter);
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!draft.name.trim() || !draft.price) return; setItems((current) => [...current, { id: uid(), name: draft.name.trim(), category: draft.category, quantity: Number(draft.quantity) || 1, estimatedPrice: Number(draft.price), actualPrice: 0, needWant: draft.needWant, priority: draft.priority, store: draft.store || 'Not chosen', purchased: false }]); setDraft({ name: '', category: 'Groceries', quantity: '1', price: '', needWant: 'Need', priority: 'Medium', store: '' }); setAdding(false); };
  return <div className="space-y-6"><SectionTitle eyebrow="Planning / today" title="Shopping list" description="Capture the decision before the aisle makes it for you." action={<Button onClick={() => setAdding(!adding)}><Plus size={16} /> Add item</Button>} />
    {adding && <form onSubmit={submit} className="surface rise rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">New list item</div><h2 className="font-display text-xl font-bold">Give this purchase a little context</h2></div><button type="button" onClick={() => setAdding(false)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label="Close item form"><X size={18} /></button></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label className="sm:col-span-2">Item name<input autoFocus required value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="e.g. replacement charger" /></label><label>Category<select value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}><option>Groceries</option><option>Household</option><option>Personal</option><option>Treats</option></select></label><label>Estimated price<input required type="number" min="0" step=".10" value={draft.price} onChange={(e) => setDraft({ ...draft, price: e.target.value })} placeholder="0.00" /></label><label>Quantity<input type="number" min="1" value={draft.quantity} onChange={(e) => setDraft({ ...draft, quantity: e.target.value })} /></label><label>Need or want<select value={draft.needWant} onChange={(e) => setDraft({ ...draft, needWant: e.target.value as NeedWant })}><option>Need</option><option>Want</option><option>Unsure</option></select></label><label>Priority<select value={draft.priority} onChange={(e) => setDraft({ ...draft, priority: e.target.value as Priority })}><option>High</option><option>Medium</option><option>Low</option></select></label><label>Preferred store<input value={draft.store} onChange={(e) => setDraft({ ...draft, store: e.target.value })} placeholder="Optional" /></label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> Save item</Button></div></form>}
    <div className="flex flex-wrap gap-2">{(['All', 'Need', 'Want', 'Unsure'] as const).map((value) => <button key={value} onClick={() => setFilter(value)} data-testid={`filter-list-${value.toLowerCase()}`} className={`rounded-full px-3.5 py-2 text-xs font-semibold transition ${filter === value ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}>{value}{value !== 'All' && <span className="ml-1.5 opacity-70">{items.filter((item) => item.needWant === value).length}</span>}</button>)}</div>
    <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.5fr_.8fr_.8fr_.8fr_1fr_auto] gap-4 border-b border-border px-5 py-3 text-[10px] font-bold uppercase tracking-[.13em] text-muted-foreground md:grid"><div>Item</div><div>Signal</div><div>Priority</div><div>Estimate</div><div>Store</div><div /></div>{visible.length === 0 ? <div className="p-6"><EmptyState title="Nothing in this view" copy="Try another filter or add the next thing you are considering." action={<Button onClick={() => setAdding(true)}><Plus size={15} /> Add item</Button>} /></div> : visible.map((item) => <div key={item.id} className={`grid gap-3 border-b border-border px-5 py-4 last:border-0 md:grid-cols-[1.5fr_.8fr_.8fr_.8fr_1fr_auto] md:items-center ${item.purchased ? 'opacity-55' : ''}`} data-testid={`row-shopping-item-${item.id}`}><div className="flex items-center gap-3"><button onClick={() => setItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, purchased: !entry.purchased } : entry))} className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg border ${item.purchased ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:border-primary'}`} aria-label={`Mark ${item.name} ${item.purchased ? 'not purchased' : 'purchased'}`} data-testid={`toggle-purchased-${item.id}`}>{item.purchased && <Check size={15} />}</button><div><div className={`text-sm font-semibold ${item.purchased ? 'line-through' : ''}`}>{item.name}</div><div className="text-xs text-muted-foreground">{item.quantity} × {money(item.estimatedPrice)} · {item.category}</div></div></div><div><Tag tone={item.needWant === 'Need' ? 'teal' : item.needWant === 'Want' ? 'coral' : 'gold'}>{item.needWant}</Tag></div><div className="text-xs font-semibold text-muted-foreground">{item.priority}</div><div className="font-mono text-sm">{money(item.estimatedPrice * item.quantity)}</div><div className="text-xs text-muted-foreground">{item.store}</div><button onClick={() => { if (window.confirm(`Remove ${item.name} from the list?`)) setItems((current) => current.filter((entry) => entry.id !== item.id)); }} className="justify-self-end rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Delete ${item.name}`} data-testid={`delete-shopping-item-${item.id}`}><Trash2 size={16} /></button></div>)}</div>
  </div>;
}

