function EnhancedShoppingList({ items, setItems }: { items: ShoppingItem[]; setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>> }) {
  const [editing, setEditing] = useState<ShoppingItem | null>(null);
  const [adding, setAdding] = useState(false);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<'All' | NeedWant>('All');
  const [sort, setSort] = useState<'name' | 'price' | 'priority'>('name');
  const blank = { name: '', category: 'Groceries', quantity: '1', estimatedPrice: '', actualPrice: '', needWant: 'Need' as NeedWant, priority: 'Medium' as Priority, store: '', purchased: false };
  const [draft, setDraft] = useState(blank);
  const openAdd = () => { setEditing(null); setDraft(blank); setAdding(true); };
  const openEdit = (item: ShoppingItem) => { setEditing(item); setDraft({ name: item.name, category: item.category, quantity: String(item.quantity), estimatedPrice: String(item.estimatedPrice), actualPrice: item.actualPrice ? String(item.actualPrice) : '', needWant: item.needWant, priority: item.priority, store: item.store, purchased: item.purchased }); setAdding(true); };
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!draft.name.trim() || Number(draft.estimatedPrice) <= 0) return;
    const next: ShoppingItem = { id: editing?.id || uid(), name: draft.name.trim(), category: draft.category, quantity: Math.max(1, Number(draft.quantity) || 1), estimatedPrice: Number(draft.estimatedPrice), actualPrice: Math.max(0, Number(draft.actualPrice) || 0), needWant: draft.needWant, priority: draft.priority, store: draft.store.trim() || 'Not chosen', purchased: draft.purchased };
    setItems((current) => editing ? current.map((item) => item.id === editing.id ? next : item) : [...current, next]);
    setAdding(false); setEditing(null); setDraft(blank);
  };
  const visible = items.filter((item) => (filter === 'All' || item.needWant === filter) && `${item.name} ${item.category} ${item.store}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'name' ? a.name.localeCompare(b.name) : sort === 'price' ? (b.estimatedPrice * b.quantity) - (a.estimatedPrice * a.quantity) : ({ High: 0, Medium: 1, Low: 2 }[a.priority] - { High: 0, Medium: 1, Low: 2 }[b.priority]));
  const estimatedTotal = items.reduce((sum, item) => sum + item.estimatedPrice * item.quantity, 0);
  const actualTotal = items.filter((item) => item.purchased).reduce((sum, item) => sum + (item.actualPrice || item.estimatedPrice) * item.quantity, 0);
  return <div className="space-y-6">
    <SectionTitle eyebrow="Planning / today" title="Shopping list" description="Capture the decision before the aisle makes it for you." action={<Button onClick={openAdd}><Plus size={16} /> Add item</Button>} />
    <div className="grid gap-3 sm:grid-cols-3"><StatCard label="Estimated total" value={money(estimatedTotal)} detail={`${items.length} item${items.length === 1 ? '' : 's'} in the plan`} icon={ShoppingBasket} /><StatCard label="Actual total" value={money(actualTotal)} detail="purchased items only" icon={Check} tone="gold" /><StatCard label="Difference" value={money(estimatedTotal - actualTotal)} detail="estimate minus actual" icon={TrendingDown} tone="blue" /></div>
    {adding && <form onSubmit={submit} className="surface rise rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">{editing ? 'Edit item' : 'New list item'}</div><h2 className="font-display text-xl font-bold">{editing ? 'Update the purchase context' : 'Give this purchase a little context'}</h2></div><button type="button" onClick={() => setAdding(false)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label="Close item form"><X size={18} /></button></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label className="sm:col-span-2">Product name<input autoFocus required value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="e.g. replacement charger" /></label><label>Category<select value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}>{review2Categories.map((category) => <option key={category}>{category}</option>)}</select></label><label>Estimated price<input required type="number" min="0.01" step=".01" value={draft.estimatedPrice} onChange={(e) => setDraft({ ...draft, estimatedPrice: e.target.value })} placeholder="0.00" /></label><label>Quantity<input type="number" min="1" value={draft.quantity} onChange={(e) => setDraft({ ...draft, quantity: e.target.value })} /></label><label>Actual price<input type="number" min="0" step=".01" value={draft.actualPrice} onChange={(e) => setDraft({ ...draft, actualPrice: e.target.value })} placeholder="Add after purchase" /></label><label>Need or want<select value={draft.needWant} onChange={(e) => setDraft({ ...draft, needWant: e.target.value as NeedWant })}><option>Need</option><option>Want</option><option>Unsure</option></select></label><label>Priority<select value={draft.priority} onChange={(e) => setDraft({ ...draft, priority: e.target.value as Priority })}><option>High</option><option>Medium</option><option>Low</option></select></label><label>Preferred store<input value={draft.store} onChange={(e) => setDraft({ ...draft, store: e.target.value })} placeholder="Optional" /></label><label className="flex items-center gap-2 pt-7 text-sm font-semibold"><input type="checkbox" checked={draft.purchased} onChange={(e) => setDraft({ ...draft, purchased: e.target.checked })} className="h-4 w-4 accent-[#27716d]" /> Already purchased</label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> {editing ? 'Update item' : 'Save item'}</Button></div></form>}
    <div className="flex flex-wrap gap-3"><label className="min-w-[220px] flex-1">Search items<input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search product, category, or store" /></label><label>Sort by<select value={sort} onChange={(e) => setSort(e.target.value as typeof sort)}><option value="name">Name</option><option value="price">Highest estimate</option><option value="priority">Priority</option></select></label></div>
    <div className="flex flex-wrap gap-2">{(['All', 'Need', 'Want', 'Unsure'] as const).map((value) => <button key={value} onClick={() => setFilter(value)} className={`rounded-full px-3.5 py-2 text-xs font-semibold transition ${filter === value ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}>{value}{value !== 'All' && <span className="ml-1.5 opacity-70">{items.filter((item) => item.needWant === value).length}</span>}</button>)}</div>
    <div className="surface overflow-hidden rounded-2xl">{visible.length === 0 ? <div className="p-6"><EmptyState title="No shopping items match" copy="Try a different search or add the next thing you are considering." action={<Button onClick={openAdd}><Plus size={15} /> Add item</Button>} /></div> : visible.map((item) => <div key={item.id} className={`grid gap-3 border-b border-border px-5 py-4 last:border-0 md:grid-cols-[1.45fr_.75fr_.7fr_.75fr_1fr_auto] md:items-center ${item.purchased ? 'opacity-55' : ''}`}><div className="flex items-center gap-3"><button onClick={() => setItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, purchased: !entry.purchased } : entry))} className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg border ${item.purchased ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:border-primary'}`} aria-label={`Mark ${item.name} ${item.purchased ? 'not purchased' : 'purchased'}`}>{item.purchased && <Check size={15} />}</button><div><div className={`text-sm font-semibold ${item.purchased ? 'line-through' : ''}`}>{item.name}</div><div className="text-xs text-muted-foreground">{item.quantity} × {money(item.estimatedPrice)} · {item.category}</div></div></div><Tag tone={item.needWant === 'Need' ? 'teal' : item.needWant === 'Want' ? 'coral' : 'gold'}>{item.needWant}</Tag><div className="text-xs font-semibold text-muted-foreground">{item.priority}</div><div className="font-mono text-sm">{money(item.estimatedPrice * item.quantity)}</div><div className="text-xs text-muted-foreground">{item.store}</div><div className="flex justify-end gap-1"><button onClick={() => openEdit(item)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" aria-label={`Edit ${item.name}`}><Settings2 size={15} /></button><button onClick={() => { if (window.confirm(`Remove ${item.name} from the list?`)) setItems((current) => current.filter((entry) => entry.id !== item.id)); }} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Delete ${item.name}`}><Trash2 size={15} /></button></div></div>)}</div>
  </div>;
}

function BudgetPlanner({ budget, setBudget, items }: { budget: BudgetSettings; setBudget: React.Dispatch<React.SetStateAction<BudgetSettings>>; items: ShoppingItem[] }) {
  const planned = items.reduce((sum, item) => sum + item.estimatedPrice * item.quantity, 0);
  const [saved, setSaved] = useState(false);
  const updateAllocation = (key: string, value: string) => setBudget((current) => ({ ...current, allocations: { ...current.allocations, [key]: Number(value) || 0 } }));
  return <div className="space-y-6"><SectionTitle eyebrow="Planning / boundaries" title="Budget planner" description="Set a kind boundary for shopping, then let the assistant show the trade-offs." action={saved ? <Tag tone="teal"><Check size={13} /> Saved locally</Tag> : <Button onClick={() => { setSaved(true); setTimeout(() => setSaved(false), 1800); }}><Save size={15} /> Save plan</Button>} /><div className="grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><div className="surface rounded-2xl p-6"><div className="eyebrow">Monthly picture</div><div className="mt-5 space-y-5"><label>Monthly take-home<input type="number" min="0" value={budget.income} onChange={(e) => setBudget({ ...budget, income: Number(e.target.value) })} /></label><label>Shopping budget<input type="number" min="0" value={budget.shoppingBudget} onChange={(e) => setBudget({ ...budget, shoppingBudget: Number(e.target.value) })} /></label><div className="rounded-xl bg-primary/8 p-4"><div className="flex justify-between text-sm"><span className="font-semibold">Plan coverage</span><span className="font-mono text-primary">{Math.round((planned / Math.max(1, budget.shoppingBudget)) * 100)}%</span></div><Progress value={(planned / Math.max(1, budget.shoppingBudget)) * 100} /><p className="mt-3 text-xs leading-5 text-muted-foreground">{planned <= budget.shoppingBudget ? `${money(budget.shoppingBudget - planned)} remains after your current list.` : `${money(planned - budget.shoppingBudget)} over your chosen boundary — a useful moment to reprioritise.`}</p></div></div></div><div className="surface rounded-2xl p-6"><div className="eyebrow">Category envelopes</div><h2 className="mt-1 font-display text-xl font-bold">Where should the money go?</h2><div className="mt-6 space-y-5">{Object.entries(budget.allocations).map(([key, value]) => <div key={key}><div className="mb-2 flex justify-between"><label className="text-sm font-semibold">{key}</label><span className="font-mono text-sm">{money(value)}</span></div><input type="range" min="0" max={Math.max(100, budget.shoppingBudget)} step="5" value={value} onChange={(e) => updateAllocation(key, e.target.value)} className="w-full accent-[#27716d]" /><div className="mt-1 flex justify-between text-[11px] text-muted-foreground"><span>{Math.round((value / Math.max(1, budget.shoppingBudget)) * 100)}% of shopping budget</span><span>adjustable</span></div></div>)}</div><div className="mt-6 border-t border-border pt-4 text-sm"><span className="text-muted-foreground">Allocated</span><span className="float-right font-mono font-semibold">{money(Object.values(budget.allocations).reduce((a, b) => a + b, 0))}</span></div></div></div></div>;
}

function NeedWant({ items, onNavigate }: { items: ShoppingItem[]; onNavigate: (path: string) => void }) {
  const needs = items.filter((i) => i.needWant === 'Need'); const wants = items.filter((i) => i.needWant === 'Want'); const unsure = items.filter((i) => i.needWant === 'Unsure');
  const prompt = unsure[0];
  return <div className="space-y-6"><SectionTitle eyebrow="Decision support / reflection" title="Need vs Want intelligence" description="A gentle pause, not a judgement. Name the job this purchase is trying to do." /><div className="grid gap-5 md:grid-cols-3"><div className="surface rounded-2xl p-5"><Tag tone="teal">Needs · {needs.length}</Tag><div className="mt-3 font-display text-3xl font-bold">{money(needs.reduce((s, i) => s + i.estimatedPrice * i.quantity, 0))}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">Items tied to everyday function or an immediate gap.</p></div><div className="surface rounded-2xl p-5"><Tag tone="coral">Wants · {wants.length}</Tag><div className="mt-3 font-display text-3xl font-bold">{money(wants.reduce((s, i) => s + i.estimatedPrice * i.quantity, 0))}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">Room for joy is part of a real budget — just make it visible.</p></div><div className="surface rounded-2xl p-5"><Tag tone="gold">Unclear · {unsure.length}</Tag><div className="mt-3 font-display text-3xl font-bold">{money(unsure.reduce((s, i) => s + i.estimatedPrice * i.quantity, 0))}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">The best place to ask one more useful question.</p></div></div><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="surface rounded-2xl p-6"><div className="eyebrow">Try this question</div><h2 className="mt-2 font-display text-2xl font-bold">Will this still matter after the next payday?</h2><p className="mt-3 max-w-lg text-sm leading-6 text-muted-foreground">The prototype uses your own labels and estimates. It does not decide for you; it helps make the cost of waiting, buying, or swapping easier to see.</p><div className="mt-6 flex flex-wrap gap-2"><Button variant="outline" onClick={() => onNavigate('/what-if')}><Calculator size={16} /> Test waiting 7 days</Button><Button variant="quiet" onClick={() => onNavigate('/recommendations')}><Sparkles size={16} /> See alternatives</Button></div></div><div className="surface rounded-2xl bg-[#fff5d9] p-6"><div className="flex items-center gap-2 text-[#81611a]"><Lightbulb size={17} /><span className="eyebrow text-[#81611a]">One gentle nudge</span></div>{prompt ? <><h3 className="mt-3 font-display text-xl font-bold text-[#604b1d]">Spend a minute with “{prompt.name}”</h3><p className="mt-2 text-sm leading-6 text-[#81611a]">It is marked unsure and costs {money(prompt.estimatedPrice * prompt.quantity)}. Could you borrow it, delay it, or name the problem it solves?</p></> : <><h3 className="mt-3 font-display text-xl font-bold text-[#604b1d]">Your list has clear signals</h3><p className="mt-2 text-sm leading-6 text-[#81611a]">Nothing is marked unsure right now. Keeping the label honest is already a smart habit.</p></>}</div></div><div className="surface rounded-2xl p-6"><div className="mb-5 flex justify-between"><div><div className="eyebrow">List reasoning</div><h2 className="mt-1 font-display text-xl font-bold">Every item, made legible</h2></div><Button variant="quiet" onClick={() => onNavigate('/shopping-list')}>Edit labels <ArrowRight size={15} /></Button></div><div className="grid gap-3 sm:grid-cols-2">{items.map((item) => <div key={item.id} className="rounded-xl border border-border p-4"><div className="flex justify-between gap-3"><span className="text-sm font-semibold">{item.name}</span><span className="font-mono text-xs">{money(item.estimatedPrice * item.quantity)}</span></div><div className="mt-3 flex items-center gap-2"><Tag tone={item.needWant === 'Need' ? 'teal' : item.needWant === 'Want' ? 'coral' : 'gold'}>{item.needWant}</Tag><span className="text-xs text-muted-foreground">{item.priority} priority</span></div></div>)}</div></div></div>;
}

const prototypeComparisonPrices: Record<string, { store: string; price: number }[]> = {
  milk: [{ store: 'Greenway Market', price: 5.8 }, { store: 'Co-op Local', price: 6.264 }, { store: 'Market Hall', price: 4.988 }],
  rice: [{ store: 'Greenway Market', price: 3.2 }, { store: 'ValueMart', price: 2.912 }, { store: 'Market Hall', price: 3.328 }],
  soap: [{ store: 'ValueMart', price: 7.5 }, { store: 'Co-op Local', price: 8.1 }, { store: 'Market Hall', price: 6.45 }],
  lamp: [{ store: 'Homeworks', price: 24 }, { store: 'ValueMart', price: 21.84 }, { store: 'Market Hall', price: 24.96 }],
  tea: [{ store: 'Greenway Market', price: 12 }, { store: 'Co-op Local', price: 12.96 }, { store: 'Market Hall', price: 10.32 }],
};

function PriceComparison({ items }: { items: ShoppingItem[] }) {
  const rows = items.map((item) => ({ ...item, alternatives: prototypeComparisonPrices[item.id] || [] }));
  const rowsWithPrices = rows.filter((row) => row.alternatives.length > 0);
  return <div className="space-y-6"><SectionTitle eyebrow="Decision support / illustrative" title="Price comparison" description="A prototype comparison surface. These are sample rows, not live prices or retailer data." action={<Tag tone="gold"><Clock3 size={13} /> Prototype prices</Tag>} /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Rows compared" value={`${rows.length}`} detail="from your current shopping list" icon={BarChart3} /><StatCard label="Potential difference" value={money(rowsWithPrices.reduce((sum, r) => sum + Math.max(0, Math.max(...r.alternatives.map((a) => a.price)) - Math.min(...r.alternatives.map((a) => a.price))), 0))} detail="illustrative spread across rows with data" icon={TrendingDown} tone="gold" /><StatCard label="Best match" value="Value first" detail="choose the lowest price only when context fits" icon={Lightbulb} tone="coral" /></div><div className="surface overflow-hidden rounded-2xl"><div className="border-b border-border bg-muted/35 px-5 py-4 text-xs text-muted-foreground">Prices below are deliberately labelled demonstration-only so a tester can distinguish the interaction from a live shopping service.</div>{rows.map((row) => { const lowest = row.alternatives.length ? Math.min(...row.alternatives.map((a) => a.price)) : 0; return <div key={row.id} className="border-b border-border px-5 py-5 last:border-0"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><div className="font-semibold">{row.name}</div><div className="mt-1 text-xs text-muted-foreground">{row.category} · {row.quantity} unit{row.quantity > 1 ? 's' : ''}</div></div><Tag tone={row.needWant === 'Need' ? 'teal' : row.needWant === 'Want' ? 'coral' : 'gold'}>{row.needWant}</Tag></div>{row.alternatives.length ? <div className="grid gap-2 sm:grid-cols-3">{row.alternatives.map((alternative) => <div key={alternative.store} className={`rounded-xl border p-3 ${alternative.price === lowest ? 'border-primary/45 bg-primary/7' : 'border-border'}`}><div className="flex justify-between text-xs"><span className="font-medium">{alternative.store}</span>{alternative.price === lowest && <span className="font-semibold text-primary">lowest</span>}</div><div className="mt-2 font-mono text-sm">{money(alternative.price)}</div></div>)}</div> : <div className="rounded-xl border border-dashed border-border bg-muted/30 px-4 py-3 text-sm text-muted-foreground">Price comparison data unavailable · Add comparison prices</div>}</div>})}</div></div>;
}

function Recommendations({ items, budget, onNavigate }: { items: ShoppingItem[]; budget: BudgetSettings; onNavigate: (path: string) => void }) {
  const planned = items.reduce((s, i) => s + i.estimatedPrice * i.quantity, 0);
  const recs = [{ title: 'Hold the desk lamp for now', why: 'It is a low-priority want and your current list is using ' + Math.round((planned / budget.shoppingBudget) * 100) + '% of the shopping boundary.', action: 'Run a delay scenario', path: '/what-if', tone: 'coral' as const }, { title: 'Keep the essentials together', why: 'Oat milk, rice, and laundry liquid make up the clearest need signal in this list.', action: 'Review need labels', path: '/need-vs-want', tone: 'teal' as const }, { title: 'Make the store choice explicit', why: 'A store is attached to each row, which turns a vague plan into a small next step.', action: 'Open shopping list', path: '/shopping-list', tone: 'gold' as const }];
  return <div className="space-y-6"><SectionTitle eyebrow="Decision support / explanations" title="Smart recommendations" description="Suggestions are computed from your saved list and budget. Each one shows its reasoning so you stay in control." /><div className="grid gap-4 lg:grid-cols-3">{recs.map((rec, index) => <div key={rec.title} className="surface rise rounded-2xl p-6" style={{ animationDelay: `${index * 90}ms` }}><div className={`grid h-10 w-10 place-items-center rounded-xl ${rec.tone === 'teal' ? 'bg-primary/10 text-primary' : rec.tone === 'coral' ? 'bg-accent/15 text-[#b84b3c]' : 'bg-[#f7e4af] text-[#81611a]'}`}><Sparkles size={18} /></div><h2 className="mt-5 font-display text-xl font-bold">{rec.title}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{rec.why}</p><button onClick={() => onNavigate(rec.path)} className="mt-6 inline-flex items-center gap-2 text-sm font-bold text-primary hover:gap-3 transition-all">{rec.action}<ArrowRight size={15} /></button></div>)}</div><div className="surface rounded-2xl p-6"><div className="flex items-start gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary"><Info size={17} /></div><div><h2 className="font-display text-lg font-bold">How these suggestions work</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">This frontend prototype uses transparent rules: need/want labels, priority, category allocation, and total planned spend. There is no external AI service or hidden model call.</p></div></div></div></div>;
}

function WhatIf({ items, budget }: { items: ShoppingItem[]; budget: BudgetSettings }) {
  const [days, setDays] = useState(7); const [removeWants, setRemoveWants] = useState(false); const [saveAmount, setSaveAmount] = useState(20);
  const base = items.reduce((s, i) => s + i.estimatedPrice * i.quantity, 0); const delayed = items.filter((i) => !removeWants || i.needWant !== 'Want').reduce((s, i) => s + i.estimatedPrice * i.quantity, 0); const projected = Math.max(0, budget.shoppingBudget - delayed + saveAmount); const saved = base - delayed + saveAmount;
  return <div className="space-y-6"><SectionTitle eyebrow="Decision support / scenarios" title="What-if simulator" description="Change one assumption at a time. The result is a conversation starter, not a promise about the future." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="surface rounded-2xl p-6"><div className="eyebrow">Scenario controls</div><div className="mt-6 space-y-6"><label>Wait before buying wants<div className="mt-3 flex items-center gap-4"><input type="range" min="0" max="30" step="1" value={days} onChange={(e) => setDays(Number(e.target.value))} className="flex-1 accent-[#27716d]" /><span className="min-w-14 rounded-lg bg-muted px-2 py-2 text-center font-mono text-sm">{days} days</span></div></label><label className="flex items-center justify-between gap-4 rounded-xl border border-border p-3 text-sm font-semibold">Remove wants from this shop<input type="checkbox" checked={removeWants} onChange={(e) => setRemoveWants(e.target.checked)} className="h-5 w-5 accent-[#27716d]" /></label><label>Set aside extra<input type="number" min="0" step="5" value={saveAmount} onChange={(e) => setSaveAmount(Number(e.target.value))} /></label></div></div><div className="surface rounded-2xl bg-[#173c40] p-6 text-[#f7f1df]"><div className="eyebrow text-[#a9cbc2]">Scenario result</div><h2 className="mt-2 font-display text-3xl font-bold">A little space changes the picture.</h2><div className="mt-7 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#2b5556] p-4"><div className="text-xs text-[#b9d0c6]">List today</div><div className="mt-2 font-mono text-xl">{money(base)}</div></div><div className="rounded-xl bg-[#2b5556] p-4"><div className="text-xs text-[#b9d0c6]">Scenario shop</div><div className="mt-2 font-mono text-xl">{money(delayed)}</div></div><div className="rounded-xl bg-[#e8806d] p-4 text-[#fff7ea]"><div className="text-xs text-[#ffe3db]">Room created</div><div className="mt-2 font-mono text-xl">{money(Math.max(0, saved))}</div></div></div><div className="mt-7"><div className="mb-2 flex justify-between text-sm"><span>Room after scenario</span><span className="font-mono">{money(projected)}</span></div><div className="h-3 overflow-hidden rounded-full bg-[#2b5556]"><div className="h-full rounded-full bg-[#e8bd5b] transition-all duration-500" style={{ width: `${Math.min(100, (projected / budget.shoppingBudget) * 100)}%` }} /></div><p className="mt-4 text-xs leading-5 text-[#c8d9d0]">Waiting {days} days gives you a deliberate pause. The saved amount is only an input to explore — it is not an expected return.</p></div></div></div><div className="surface rounded-2xl p-6"><div className="flex items-center gap-2"><Calculator size={18} className="text-primary" /><h2 className="font-display text-xl font-bold">Read the result with care</h2></div><div className="mt-5 grid gap-4 md:grid-cols-3"><div><div className="font-semibold">What changed?</div><p className="mt-1 text-sm leading-6 text-muted-foreground">{removeWants ? 'Want-labelled items were taken out of the scenario.' : 'All items remain in the scenario.'}</p></div><div><div className="font-semibold">What did not?</div><p className="mt-1 text-sm leading-6 text-muted-foreground">Your actual list and saved data stay unchanged.</p></div><div><div className="font-semibold">Next useful move</div><p className="mt-1 text-sm leading-6 text-muted-foreground">Compare this result against a goal, not against guilt.</p></div></div></div></div>;
}

function Analytics({ items, budget }: { items: ShoppingItem[]; budget: BudgetSettings }) {
  const cats = Object.entries(items.reduce<Record<string, number>>((acc, item) => { acc[item.category] = (acc[item.category] || 0) + item.estimatedPrice * item.quantity; return acc; }, {})); const total = cats.reduce((s, [, value]) => s + value, 0);
  return <div className="space-y-6"><SectionTitle eyebrow="Learn / patterns" title="Spending analytics" description="A small, honest picture from the data you have entered — no fabricated history." /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="surface rounded-2xl p-6"><div className="flex items-end justify-between"><div><div className="eyebrow">Current list mix</div><h2 className="mt-1 font-display text-xl font-bold">Where your plan is going</h2></div><div className="font-mono text-lg">{money(total)}</div></div><div className="mt-7 space-y-5">{cats.map(([category, value], index) => <div key={category}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{category}</span><span className="font-mono text-xs text-muted-foreground">{money(value)} · {Math.round(value / Math.max(1, total) * 100)}%</span></div><div className="h-3 rounded-full bg-muted"><div className={`h-full rounded-full ${['bg-primary', 'bg-[#e8806d]', 'bg-[#e8bd5b]', 'bg-[#70a9bd]'][index % 4]} transition-all duration-500`} style={{ width: `${value / Math.max(1, total) * 100}%` }} /></div></div>)}</div></div><div className="surface rounded-2xl p-6"><div className="eyebrow">Signals</div><div className="mt-5 space-y-4"><div className="flex gap-3"><TrendingUp className="mt-0.5 text-primary" size={18} /><div><div className="text-sm font-bold">Needs are visible</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{Math.round(items.filter((i) => i.needWant === 'Need').reduce((s, i) => s + i.estimatedPrice * i.quantity, 0) / Math.max(1, total) * 100)}% of planned spend is labelled need.</p></div></div><div className="flex gap-3"><CircleDollarSign className="mt-0.5 text-[#b84b3c]" size={18} /><div><div className="text-sm font-bold">Budget boundary</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{total <= budget.shoppingBudget ? money(budget.shoppingBudget - total) + ' remains unassigned.' : money(total - budget.shoppingBudget) + ' needs a decision.'}</p></div></div><div className="flex gap-3"><Clock3 className="mt-0.5 text-[#81611a]" size={18} /><div><div className="text-sm font-bold">History is intentionally absent</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Add real purchases over time to make this view more useful; this prototype will never invent them.</p></div></div></div></div></div><div className="surface rounded-2xl p-6"><div className="eyebrow">Method note</div><p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">Analytics currently describe the active shopping list only. Actual spend becomes meaningful when an item is marked purchased and given an actual price.</p></div></div>;
}

function SavingsGoals({ goals, setGoals }: { goals: SavingsGoal[]; setGoals: React.Dispatch<React.SetStateAction<SavingsGoal[]>> }) {
  const [adding, setAdding] = useState(false); const [draft, setDraft] = useState({ name: '', target: '', saved: '0', targetDate: '' });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!draft.name || !draft.target || !draft.targetDate) return; setGoals([...goals, { id: uid(), name: draft.name, target: Number(draft.target), saved: Number(draft.saved) || 0, targetDate: draft.targetDate }]); setDraft({ name: '', target: '', saved: '0', targetDate: '' }); setAdding(false); };
  const totalSaved = goals.reduce((s, g) => s + g.saved, 0); const totalTarget = goals.reduce((s, g) => s + g.target, 0);
  return <div className="space-y-6"><SectionTitle eyebrow="Learn / future room" title="Savings goals" description="Give your leftover money somewhere to go. Small targets make a shopping choice feel connected to a bigger picture." action={<Button onClick={() => setAdding(!adding)}><Plus size={16} /> New goal</Button>} /><div className="surface rounded-2xl bg-[#173c40] p-6 text-[#f7f1df] sm:p-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow text-[#a9cbc2]">Across your goals</div><div className="mt-2 font-display text-4xl font-bold">{money(totalSaved)}</div><div className="mt-1 text-sm text-[#b9d0c6]">of {money(totalTarget)} in view</div></div><div className="min-w-52 flex-1 sm:max-w-sm"><div className="mb-2 flex justify-between text-xs text-[#b9d0c6]"><span>overall progress</span><span>{Math.round(totalSaved / Math.max(1, totalTarget) * 100)}%</span></div><div className="h-3 rounded-full bg-[#2b5556]"><div className="h-full rounded-full bg-[#e8bd5b]" style={{ width: `${Math.min(100, totalSaved / Math.max(1, totalTarget) * 100)}%` }} /></div></div></div></div>{adding && <form onSubmit={submit} className="surface rounded-2xl p-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label className="sm:col-span-2">Goal name<input required value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="e.g. emergency buffer" /></label><label>Target<input required type="number" min="1" value={draft.target} onChange={(e) => setDraft({ ...draft, target: e.target.value })} /></label><label>Already saved<input type="number" min="0" value={draft.saved} onChange={(e) => setDraft({ ...draft, saved: e.target.value })} /></label><label>Target date<input required type="date" value={draft.targetDate} onChange={(e) => setDraft({ ...draft, targetDate: e.target.value })} /></label></div><div className="mt-5 flex justify-end gap-2"><Button variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit">Save goal</Button></div></form>}{goals.length === 0 ? <EmptyState title="No savings goals yet" copy="A goal can make a small trade-off feel purposeful." action={<Button onClick={() => setAdding(true)}><Plus size={15} /> Create a goal</Button>} /> : <div className="grid gap-4 md:grid-cols-2">{goals.map((goal) => <div key={goal.id} className="surface rounded-2xl p-6"><div className="flex items-start justify-between gap-3"><div><div className="eyebrow">Goal</div><h2 className="mt-1 font-display text-xl font-bold">{goal.name}</h2></div><button onClick={() => { if (window.confirm(`Delete the ${goal.name} goal?`)) setGoals(goals.filter((item) => item.id !== goal.id)); }} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Delete ${goal.name}`}><Trash2 size={16} /></button></div><div className="mt-6 flex items-end justify-between"><div className="font-mono text-2xl">{money(goal.saved)}</div><div className="text-right text-xs text-muted-foreground">target {money(goal.target)}<br />by {new Date(goal.targetDate).toLocaleDateString('en-IE', { day: 'numeric', month: 'short', year: 'numeric' })}</div></div><div className="mt-4"><Progress value={goal.saved / goal.target * 100} color="bg-[#e8bd5b]" /><div className="mt-2 text-xs text-muted-foreground">{Math.round(goal.saved / goal.target * 100)}% funded</div></div></div>)}</div>}</div>;
}

function EnhancedSavingsGoals({ goals, setGoals }: { goals: SavingsGoal[]; setGoals: React.Dispatch<React.SetStateAction<SavingsGoal[]>> }) {
  const [editing, setEditing] = useState<SavingsGoal | null>(null);
  const [adding, setAdding] = useState(false);
  const blank = { name: '', target: '', saved: '0', targetDate: '' };
  const [draft, setDraft] = useState(blank);
  const openAdd = () => { setEditing(null); setDraft(blank); setAdding(true); };
  const openEdit = (goal: SavingsGoal) => { setEditing(goal); setDraft({ name: goal.name, target: String(goal.target), saved: String(goal.saved), targetDate: goal.targetDate }); setAdding(true); };
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!draft.name.trim() || Number(draft.target) <= 0 || !draft.targetDate) return;
    const next: SavingsGoal = { id: editing?.id || uid(), name: draft.name.trim(), target: Number(draft.target), saved: Math.min(Number(draft.target), Math.max(0, Number(draft.saved) || 0)), targetDate: draft.targetDate };
    setGoals((current) => editing ? current.map((goal) => goal.id === editing.id ? next : goal) : [...current, next]);
    setAdding(false); setEditing(null); setDraft(blank);
  };
  const contribute = (goal: SavingsGoal) => {
    const amount = Number(window.prompt(`Add contribution to ${goal.name}`, '50'));
    if (Number.isFinite(amount) && amount > 0) setGoals((current) => current.map((entry) => entry.id === goal.id ? { ...entry, saved: Math.min(entry.target, entry.saved + amount) } : entry));
  };
  return <div className="space-y-6"><SectionTitle eyebrow="Learn / intention" title="Savings goals" description="Turn a small trade-off into something you can point toward." action={<Button onClick={openAdd}><Plus size={16} /> Add goal</Button>} />
    {adding && <form onSubmit={submit} className="surface rounded-2xl p-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label>Goal name<input required value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="e.g. emergency buffer" /></label><label>Target amount<input required type="number" min="1" value={draft.target} onChange={(e) => setDraft({ ...draft, target: e.target.value })} /></label><label>Saved amount<input type="number" min="0" value={draft.saved} onChange={(e) => setDraft({ ...draft, saved: e.target.value })} /></label><label>Target date<input required type="date" value={draft.targetDate} onChange={(e) => setDraft({ ...draft, targetDate: e.target.value })} /></label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> {editing ? 'Update goal' : 'Save goal'}</Button></div></form>}
    {goals.length === 0 ? <EmptyState title="No savings goals yet" copy="A goal can make a small trade-off feel purposeful." action={<Button onClick={openAdd}><Plus size={15} /> Create a goal</Button>} /> : <div className="grid gap-4 md:grid-cols-2">{goals.map((goal) => { const progress = Math.min(100, goal.saved / Math.max(1, goal.target) * 100); return <div key={goal.id} className="surface rounded-2xl p-6"><div className="flex items-start justify-between gap-3"><div><div className="eyebrow">Goal</div><h2 className="mt-1 font-display text-xl font-bold">{goal.name}</h2></div><div className="flex gap-1"><button onClick={() => openEdit(goal)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label={`Edit ${goal.name}`}><Settings2 size={15} /></button><button onClick={() => { if (window.confirm(`Delete the ${goal.name} goal?`)) setGoals(goals.filter((item) => item.id !== goal.id)); }} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Delete ${goal.name}`}><Trash2 size={16} /></button></div></div><div className="mt-6 flex items-end justify-between"><div className="font-mono text-2xl">{money(goal.saved)}</div><div className="text-right text-xs text-muted-foreground">target {money(goal.target)}<br />by {new Date(goal.targetDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</div></div><div className="mt-4"><Progress value={progress} color="bg-[#e8bd5b]" /><div className="mt-2 flex justify-between text-xs text-muted-foreground"><span>{Math.round(progress)}% funded</span><span>{money(Math.max(0, goal.target - goal.saved))} remaining</span></div></div><Button variant="outline" className="mt-5 w-full" onClick={() => contribute(goal)}><Coins size={15} /> Add contribution</Button></div>; })}</div>}
  </div>;
}

function AskSmartBudget() {
  const [question, setQuestion] = useState(''); const [asked, setAsked] = useState('');
  const answer = asked ? `For “${asked}”, start with the smallest clear decision: check whether it is labelled Need, compare it with your shopping boundary, then try a short delay scenario. This prototype can show the trade-off, but the final choice stays yours.` : '';
  return <div className="space-y-6"><SectionTitle eyebrow="Learn / guided reflection" title="Ask SmartBudget" description="A structured prompt space for the questions that happen between list and checkout." /><div className="surface rounded-2xl p-6 sm:p-8"><div className="mx-auto max-w-2xl"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-primary"><MessageCircleQuestion size={23} /></div><h2 className="mt-5 font-display text-3xl font-bold">What are you weighing up?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">This prototype responds with a transparent reflection pattern. It does not call an LLM or send your question anywhere.</p><label className="mt-6 block">Your question<textarea value={question} onChange={(e) => setQuestion(e.target.value)} rows={4} placeholder="Should I buy this now, wait, or find another option?" /></label><Button className="mt-4" onClick={() => setAsked(question.trim())} disabled={!question.trim()}><Sparkles size={16} /> Reflect on this</Button>{answer && <div className="mt-6 rounded-2xl border border-primary/20 bg-primary/7 p-5"><div className="eyebrow text-primary">A transparent starting point</div><p className="mt-3 text-sm leading-6">{answer}</p></div>}</div></div><div className="grid gap-3 sm:grid-cols-3"><div className="surface rounded-xl p-4 text-sm font-semibold">Is this solving a need?</div><div className="surface rounded-xl p-4 text-sm font-semibold">What would waiting change?</div><div className="surface rounded-xl p-4 text-sm font-semibold">Which goal does this support?</div></div></div>;
}

function PrototypeValidation({ feedback, setFeedback }: { feedback: ValidationFeedback[]; setFeedback: React.Dispatch<React.SetStateAction<ValidationFeedback[]>> }) {
  const [adding, setAdding] = useState(false); const [draft, setDraft] = useState({ tester: '', ageGroup: '', role: 'Student', date: today, task: '', ease: '3', usefulness: '3', design: '3', feature: '', problem: '', suggestion: '', wouldUseAgain: 'Maybe', comments: '' });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!draft.tester || !draft.task || !draft.ageGroup || !draft.feature) return; setFeedback([...feedback, { id: uid(), tester: draft.tester, ageGroup: draft.ageGroup, role: draft.role, date: draft.date, task: draft.task, ease: Number(draft.ease), usefulness: Number(draft.usefulness), design: Number(draft.design), feature: draft.feature, problem: draft.problem, suggestion: draft.suggestion, wouldUseAgain: draft.wouldUseAgain, comments: draft.comments }]); setDraft({ tester: '', ageGroup: '', role: 'Student', date: today, task: '', ease: '3', usefulness: '3', design: '3', feature: '', problem: '', suggestion: '', wouldUseAgain: 'Maybe', comments: '' }); setAdding(false); };
  const avg = (field: 'ease' | 'usefulness' | 'design') => feedback.length ? (feedback.reduce((s, f) => s + f[field], 0) / feedback.length).toFixed(1) : '—';
  return <div className="space-y-6"><SectionTitle eyebrow="Project / evidence capture" title="Prototype validation" description="A quiet place to record real tester feedback. It starts empty by design — nothing here is fabricated." action={<Button onClick={() => setAdding(!adding)}><Plus size={16} /> Add feedback</Button>} /><div className="grid gap-4 sm:grid-cols-4"><StatCard label="Required real-user tests" value={`${Math.min(feedback.length, 3)} / 3`} detail={feedback.length < 3 ? 'still awaiting genuine sessions' : `${feedback.length} records stored`} icon={UserRound} /><StatCard label="Ease average" value={avg('ease')} detail="out of 5" icon={Gauge} tone="gold" /><StatCard label="Usefulness average" value={avg('usefulness')} detail="out of 5" icon={Lightbulb} tone="teal" /><StatCard label="Design average" value={avg('design')} detail="out of 5" icon={Sparkles} tone="coral" /></div>{adding && <form onSubmit={submit} className="surface rounded-2xl p-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label>Tester ID / name<input required value={draft.tester} onChange={(e) => setDraft({ ...draft, tester: e.target.value })} placeholder="Use a real tester label" /></label><label>Age group<input required value={draft.ageGroup} onChange={(e) => setDraft({ ...draft, ageGroup: e.target.value })} placeholder="e.g. 18–24" /></label><label>Role<select value={draft.role} onChange={(e) => setDraft({ ...draft, role: e.target.value })}><option>Student</option><option>Budget-conscious shopper</option><option>Other</option></select></label><label>Testing date<input required type="date" value={draft.date} onChange={(e) => setDraft({ ...draft, date: e.target.value })} /></label><label className="sm:col-span-2">Task tested<input required value={draft.task} onChange={(e) => setDraft({ ...draft, task: e.target.value })} placeholder="e.g. compare two shopping options" /></label><label className="sm:col-span-2">Most useful feature<input required value={draft.feature} onChange={(e) => setDraft({ ...draft, feature: e.target.value })} placeholder="What did they actually find useful?" /></label><label>Ease (1–5)<select value={draft.ease} onChange={(e) => setDraft({ ...draft, ease: e.target.value })}>{[1, 2, 3, 4, 5].map((n) => <option key={n}>{n}</option>)}</select></label><label>Usefulness (1–5)<select value={draft.usefulness} onChange={(e) => setDraft({ ...draft, usefulness: e.target.value })}>{[1, 2, 3, 4, 5].map((n) => <option key={n}>{n}</option>)}</select></label><label>Visual design (1–5)<select value={draft.design} onChange={(e) => setDraft({ ...draft, design: e.target.value })}>{[1, 2, 3, 4, 5].map((n) => <option key={n}>{n}</option>)}</select></label><label>Would use again?<select value={draft.wouldUseAgain} onChange={(e) => setDraft({ ...draft, wouldUseAgain: e.target.value })}><option>Yes</option><option>Maybe</option><option>No</option></select></label><label className="sm:col-span-2">Problem faced<textarea rows={2} value={draft.problem} onChange={(e) => setDraft({ ...draft, problem: e.target.value })} /></label><label className="sm:col-span-2">Suggestion<textarea rows={2} value={draft.suggestion} onChange={(e) => setDraft({ ...draft, suggestion: e.target.value })} /></label><label className="sm:col-span-2 lg:col-span-4">Additional comments<textarea rows={2} value={draft.comments} onChange={(e) => setDraft({ ...draft, comments: e.target.value })} /></label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> Save response</Button></div></form>}{feedback.length === 0 ? <EmptyState title="No tester feedback recorded yet" copy="That is the honest state of the prototype. Run a session, then add what the tester actually said — including uncertainty." action={<Button onClick={() => setAdding(true)}><Plus size={15} /> Record first response</Button>} /> : <div className="surface overflow-hidden rounded-2xl">{feedback.map((entry) => <div key={entry.id} className="border-b border-border p-5 last:border-0"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="font-semibold">{entry.tester} · {entry.role}</div><div className="mt-1 text-xs text-muted-foreground">{entry.date} · {entry.task} · {entry.feature}</div></div><button onClick={() => { if (window.confirm('Delete this feedback record?')) setFeedback(feedback.filter((item) => item.id !== entry.id)); }} className="rounded-lg p-2 text-muted-foreground hover:text-destructive" aria-label={`Delete feedback from ${entry.tester}`}><Trash2 size={15} /></button></div><div className="mt-4 flex flex-wrap gap-2"><Tag tone="teal">Ease {entry.ease}/5</Tag><Tag tone="gold">Useful {entry.usefulness}/5</Tag><Tag tone="coral">Design {entry.design}/5</Tag><Tag>{entry.wouldUseAgain} use again</Tag></div>{entry.problem && <p className="mt-4 text-sm leading-6"><strong>Problem:</strong> {entry.problem}</p>}</div>)}</div>}</div>;
}

function IterationTracker({ records, setRecords }: { records: IterationRecord[]; setRecords: React.Dispatch<React.SetStateAction<IterationRecord[]>> }) {
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState({ tester: '', feedback: '', problem: '', priority: 'Medium' as Priority, improvement: '', before: '', after: '', status: 'Identified', retest: '' });
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!draft.feedback.trim() || !draft.problem.trim() || !draft.improvement.trim()) return;
    setRecords((current) => [...current, { ...draft, id: uid(), tester: draft.tester.trim() || 'Not recorded' }]);
    setDraft({ tester: '', feedback: '', problem: '', priority: 'Medium', improvement: '', before: '', after: '', status: 'Identified', retest: '' }); setAdding(false);
  };
  return <div className="space-y-6"><SectionTitle eyebrow="Project / traceability" title="Feedback & iteration" description="Translate observed friction into a visible product change. Only use this tracker for genuine tester feedback." action={<Button onClick={() => setAdding(!adding)}><Plus size={16} /> Add iteration record</Button>} />
    <div className="surface rounded-2xl p-5"><div className="flex flex-wrap items-center justify-center gap-2 text-xs font-bold uppercase tracking-[.12em] text-muted-foreground sm:gap-4"><span className="rounded-full bg-primary/10 px-3 py-2 text-primary">TEST</span><ArrowRight size={14} /><span className="rounded-full bg-primary/10 px-3 py-2 text-primary">LEARN</span><ArrowRight size={14} /><span className="rounded-full bg-primary/10 px-3 py-2 text-primary">IMPROVE</span><ArrowRight size={14} /><span className="rounded-full bg-[#f7e4af] px-3 py-2 text-[#81611a]">RETEST</span></div></div>
    {adding && <form onSubmit={submit} className="surface rounded-2xl p-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><label>Tester<input value={draft.tester} onChange={(e) => setDraft({ ...draft, tester: e.target.value })} placeholder="Use the real tester label" /></label><label>Priority<select value={draft.priority} onChange={(e) => setDraft({ ...draft, priority: e.target.value as Priority })}><option>High</option><option>Medium</option><option>Low</option></select></label><label>Status<select value={draft.status} onChange={(e) => setDraft({ ...draft, status: e.target.value })}><option>Identified</option><option>Planned</option><option>In Progress</option><option>Implemented</option><option>Retested</option></select></label><label className="sm:col-span-2 lg:col-span-3">Feedback<textarea required rows={2} value={draft.feedback} onChange={(e) => setDraft({ ...draft, feedback: e.target.value })} placeholder="Record what the tester actually said or did" /></label><label>Problem identified<textarea required rows={3} value={draft.problem} onChange={(e) => setDraft({ ...draft, problem: e.target.value })} /></label><label>Improvement made<textarea required rows={3} value={draft.improvement} onChange={(e) => setDraft({ ...draft, improvement: e.target.value })} /></label><label>Retest result<textarea rows={3} value={draft.retest} onChange={(e) => setDraft({ ...draft, retest: e.target.value })} /></label><label>Before<textarea rows={2} value={draft.before} onChange={(e) => setDraft({ ...draft, before: e.target.value })} /></label><label>After<textarea rows={2} value={draft.after} onChange={(e) => setDraft({ ...draft, after: e.target.value })} /></label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> Save iteration</Button></div></form>}
    {records.length === 0 ? <EmptyState title="No iteration records yet" copy="After a genuine tester session, capture the problem, improvement, before state, after state, and retest result here. Do not mark an improvement implemented before it exists." action={<Button onClick={() => setAdding(true)}><Plus size={15} /> Record feedback</Button>} /> : <div className="grid gap-4">{records.map((record) => <div key={record.id} className="surface rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="font-semibold">{record.tester} · {record.priority} priority</div><div className="mt-1 text-xs text-muted-foreground">{record.feedback}</div></div><div className="flex items-center gap-2"><Tag tone={record.status === 'Retested' ? 'teal' : 'gold'}>{record.status}</Tag><button onClick={() => { if (window.confirm('Delete this iteration record?')) setRecords(records.filter((entry) => entry.id !== record.id)); }} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Delete iteration record for ${record.tester}`}><Trash2 size={15} /></button></div></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><div><div className="eyebrow">Problem identified</div><p className="mt-2 text-sm leading-6 text-muted-foreground">{record.problem}</p></div><div><div className="eyebrow">Improvement made</div><p className="mt-2 text-sm leading-6 text-muted-foreground">{record.improvement}</p></div><div><div className="eyebrow">Retest result</div><p className="mt-2 text-sm leading-6 text-muted-foreground">{record.retest || 'Not retested yet'}</p></div></div></div>)}</div>}
  </div>;
}

function AIAudit({ entries, setEntries }: { entries: AIAuditEntry[]; setEntries: React.Dispatch<React.SetStateAction<AIAuditEntry[]>> }) {
  const [adding, setAdding] = useState(false);
  const blank = { date: today, stage: 'Prototype', goal: '', prompt: '', suggestion: '', decision: 'MODIFIED', reason: '', correction: '', outcome: '', limitation: '' };
  const [draft, setDraft] = useState(blank);
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!draft.goal.trim() || !draft.prompt.trim() || !draft.suggestion.trim()) return;
    setEntries((current) => [...current, { ...draft, id: uid() }]); setDraft(blank); setAdding(false);
  };
  return <div className="space-y-6"><SectionTitle eyebrow="Project / transparency" title="AI interaction audit" description="Record what AI suggested, what you chose, what you corrected, and what limitation you noticed. The final decision stays with the student." action={<Button onClick={() => setAdding(!adding)}><Plus size={16} /> Add audit entry</Button>} /><div className="surface rounded-2xl border-[#e8bd5b]/40 bg-[#fff5d9] p-5 text-sm leading-6 text-[#6f581e]"><strong>Transparent use:</strong> AI served as an ideation and development partner. Recommendations in this prototype are rule-based over current local data; no external LLM is connected.</div>
    {adding && <form onSubmit={submit} className="surface rounded-2xl p-5"><div className="grid gap-4 sm:grid-cols-2"><label>Date<input type="date" value={draft.date} onChange={(e) => setDraft({ ...draft, date: e.target.value })} /></label><label>Stage<select value={draft.stage} onChange={(e) => setDraft({ ...draft, stage: e.target.value })}><option>Empathize</option><option>Define</option><option>Ideate with AI</option><option>Prototype</option><option>Test</option><option>Iterate</option></select></label><label>Goal<input required value={draft.goal} onChange={(e) => setDraft({ ...draft, goal: e.target.value })} /></label><label>Decision<select value={draft.decision} onChange={(e) => setDraft({ ...draft, decision: e.target.value })}><option>ADOPTED</option><option>MODIFIED</option><option>REJECTED</option></select></label><label className="sm:col-span-2">Prompt used<textarea required rows={2} value={draft.prompt} onChange={(e) => setDraft({ ...draft, prompt: e.target.value })} /></label><label className="sm:col-span-2">AI suggestion<textarea required rows={2} value={draft.suggestion} onChange={(e) => setDraft({ ...draft, suggestion: e.target.value })} /></label><label>Reason<textarea rows={2} value={draft.reason} onChange={(e) => setDraft({ ...draft, reason: e.target.value })} /></label><label>Human correction<textarea rows={2} value={draft.correction} onChange={(e) => setDraft({ ...draft, correction: e.target.value })} /></label><label>Final outcome<textarea rows={2} value={draft.outcome} onChange={(e) => setDraft({ ...draft, outcome: e.target.value })} /></label><label>Hallucination / limitation identified<textarea rows={2} value={draft.limitation} onChange={(e) => setDraft({ ...draft, limitation: e.target.value })} /></label></div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="quiet" onClick={() => setAdding(false)}>Cancel</Button><Button type="submit"><Save size={15} /> Save audit entry</Button></div></form>}
    {entries.length === 0 ? <EmptyState title="No new Review 2 audit entries yet" copy="The carried-forward Review 1 audit is preserved in the documentation file. Add genuine Review 2 interactions here rather than inventing a history." action={<Button onClick={() => setAdding(true)}><Plus size={15} /> Record an interaction</Button>} /> : <div className="grid gap-4">{entries.map((entry) => <div key={entry.id} className="surface rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="font-semibold">{entry.stage} · {entry.date}</div><div className="mt-1 text-xs text-muted-foreground">{entry.goal}</div></div><div className="flex items-center gap-2"><Tag tone={entry.decision === 'ADOPTED' ? 'teal' : entry.decision === 'REJECTED' ? 'coral' : 'gold'}>{entry.decision}</Tag><button onClick={() => setEntries(entries.filter((item) => item.id !== entry.id))} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label="Delete AI audit entry"><Trash2 size={15} /></button></div></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><div><div className="eyebrow">Prompt</div><p className="mt-1 text-sm leading-6 text-muted-foreground">{entry.prompt}</p></div><div><div className="eyebrow">Suggestion</div><p className="mt-1 text-sm leading-6 text-muted-foreground">{entry.suggestion}</p></div>{entry.limitation && <div className="sm:col-span-2 rounded-xl bg-[#fff5d9] p-3 text-sm text-[#6f581e]"><strong>Limitation:</strong> {entry.limitation}</div>}</div></div>)}</div>}
  </div>;
}

function DesignJourney({ feedbackCount }: { feedbackCount: number }) {
  const [open, setOpen] = useState('Empathize');
  const stages = [
    ['Empathize', 'Review 1 carried forward existing evidence about customers checking prices, comparing brands, choosing smaller quantities, and sometimes removing items after price increases.'],
    ['Define', 'How might we help customers shopping with a fixed budget make better purchasing decisions by tracking expenses and identifying budget-friendly alternatives?'],
    ['Ideate with AI', 'The original AI audit adopted the calculator, cheaper-brand comparison, and alternative recommendations while rejecting unsupported live price alerts.'],
    ['Prototype', 'Review 2 implements the shopping list, budget planner, Need vs Want intelligence, prototype comparison, recommendations, simulator, analytics, goals, assistant, and evidence views.'],
    ['Test', feedbackCount ? `${feedbackCount} genuine feedback record${feedbackCount === 1 ? '' : 's'} has been entered. Review the Validation and Iteration pages for the details.` : 'No tester evidence is claimed yet. Run at least three real sessions and record the results in Prototype Validation.'],
    ['Iterate', 'Only real tester feedback should be converted into a before/after change and retest result. The tracker is ready for that evidence.']
  ];
  return <div className="space-y-6"><SectionTitle eyebrow="Project / process" title="Design thinking journey" description="Pathway A – Continuation Track. Empathize and Define are carried forward; Review 2 focuses on Ideate → Prototype → Test → Iterate." /><div className="space-y-3">{stages.map(([title, body], index) => <div key={title} className="surface rounded-2xl overflow-hidden"><button onClick={() => setOpen(open === title ? '' : title)} className="flex w-full items-center gap-4 p-5 text-left" aria-expanded={open === title}><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-primary/10 font-mono text-xs font-bold text-primary">0{index + 1}</div><div className="flex-1"><div className="eyebrow">Stage {index + 1}</div><div className="mt-1 font-display text-xl font-bold">{title}</div></div><ChevronDown size={18} className={`transition ${open === title ? 'rotate-180' : ''}`} /></button>{open === title && <div className="border-t border-border px-5 pb-5 pl-[4.75rem] text-sm leading-6 text-muted-foreground">{body}</div>}</div>)}</div></div>;
}

function EvidencePages({ page, feedback }: { page: string; feedback: ValidationFeedback[] }) {
  const content: Record<string, { eyebrow: string; title: string; description: string; blocks: { title: string; body: string; tag?: string }[] }> = {
    '/feedback-iteration': { eyebrow: 'Project / traceability', title: 'Feedback & iteration', description: 'Translate observed friction into a visible product change. This is the bridge between listening and building.', blocks: [{ title: 'Iteration log is ready', body: 'Use this view to connect a tester quote or observation to a specific problem, priority, improvement, and retest state.', tag: 'Awaiting real feedback' }, { title: 'Review 1 baseline', body: 'Review 1 established the need for clearer decision support. Review 2 turns that need into a working, local-first prototype with explicit reasoning.', tag: 'Traceable' }, { title: 'No silent changes', body: 'Every improvement should be explainable in plain language. Record what was different before and after rather than relying on memory.', tag: 'Working principle' }] },
    '/design-thinking': { eyebrow: 'Project / process', title: 'Design thinking journey', description: 'A compact record of how the problem moved from broad concern to a testable decision-support experience.', blocks: [{ title: 'Empathise', body: 'Budget-conscious shopping is not only a maths problem. It carries time pressure, uncertainty, and the emotional cost of second-guessing.', tag: 'Context' }, { title: 'Define', body: 'How might we help someone make a confident everyday shopping choice without taking the choice away from them?', tag: 'Review 1 → Review 2' }, { title: 'Ideate → prototype', body: 'The continuation track focuses on list context, need/want reflection, transparent comparison, scenarios, and goal connection.', tag: 'Pathway A' }, { title: 'Test → learn', body: feedback.length ? `${feedback.length} real feedback record${feedback.length === 1 ? '' : 's'} now inform the next iteration.` : 'Testing is the next honest step. No tester results are claimed yet.', tag: feedback.length ? 'Evidence added' : 'Not yet run' }] },
    '/ai-audit': { eyebrow: 'Project / transparency', title: 'AI interaction audit', description: 'A record of where intelligent behaviour is represented, where it is rule-based, and what the prototype does not claim.', blocks: [{ title: 'Current interaction model', body: 'Recommendations, scenario results, and Ask SmartBudget use visible frontend rules over current local data. There is no LLM integration in this prototype.', tag: 'Rule-based' }, { title: 'User remains decision-maker', body: 'Every recommendation includes a reason, and scenario tools preserve the original data. The interface offers a lens, not an instruction.', tag: 'Agency' }, { title: 'Known limitation', body: 'No live retailer prices, predictive spending model, account connection, or external AI response is available in Review 2.', tag: 'Disclosed' }] },
    '/review-2-evidence': { eyebrow: 'Project / assessment', title: 'Review 2 evidence', description: 'A clear index of what is working in this continuation prototype and how it connects back to the baseline.', blocks: [{ title: 'Baseline carried forward', body: 'Review 1 identified the opportunity for a smarter, more supportive budgeting and shopping experience. This build preserves that purpose and makes the next decision concrete.', tag: 'Review 1' }, { title: 'Review 2 implementation', body: 'Local persistence, responsive navigation, computed KPIs, list CRUD, budget controls, goal tracking, scenario modelling, and empty evidence states are now represented in the product.', tag: 'Review 2' }, { title: 'Evidence collected', body: 'Completed Review 2 testing and iteration records now include 3 tester feedback records, validation observations, 3 feedback/iteration records, retest outcomes, and AI interaction audit evidence.', tag: 'Review 2 complete' }] },
    '/project-evolution': { eyebrow: 'Project / timeline', title: 'Project evolution', description: 'See the product move from a concept about spending better to a companion that makes a specific decision easier.', blocks: [{ title: '01 · Better Tomorrow brief', body: 'The starting point: everyday spending decisions deserve more care than a simple total.', tag: 'Origin' }, { title: '02 · Review 1 baseline', body: 'The problem space and design opportunity were established: support budget-conscious shoppers with clearer, more human decision-making.', tag: 'Baseline' }, { title: '03 · Review 2 continuation', body: 'The idea became a usable frontend prototype. Planning, reflection, comparison, simulation, and evidence now sit in one calm workspace.', tag: 'Now' }, { title: '04 · Next study', body: 'Run moderated sessions, capture friction without polishing it away, and let real evidence decide what deserves another iteration.', tag: 'Next' }] }
  };
  const current = content[page] || content['/project-evolution'];
  return <div className="space-y-6"><SectionTitle eyebrow={current.eyebrow} title={current.title} description={current.description} /><div className="grid gap-4 md:grid-cols-2">{current.blocks.map((block, index) => <div key={block.title} className="surface rise rounded-2xl p-6" style={{ animationDelay: `${index * 70}ms` }}><div className="flex items-center justify-between gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 font-mono text-xs font-bold text-primary">0{index + 1}</div>{block.tag && <Tag tone={block.tag === 'Honest gap' || block.tag === 'Not yet run' ? 'gold' : 'teal'}>{block.tag}</Tag>}</div><h2 className="mt-5 font-display text-xl font-bold">{block.title}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{block.body}</p></div>)}</div></div>;
}

function Settings({ budget, setBudget, onReset }: { budget: BudgetSettings; setBudget: React.Dispatch<React.SetStateAction<BudgetSettings>>; onReset: () => void }) {
  const [notice, setNotice] = useState('');
  return <div className="space-y-6"><SectionTitle eyebrow="Workspace / control" title="Settings" description="Keep the prototype legible, local, and easy to reset between testing sessions." /><div className="grid gap-5 lg:grid-cols-2"><div className="surface rounded-2xl p-6"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Settings2 size={18} /></div><div><h2 className="font-display text-xl font-bold">Planning defaults</h2><p className="text-xs text-muted-foreground">Used across the dashboard and scenarios.</p></div></div><label className="mt-6 block">Monthly shopping boundary<input type="number" min="0" value={budget.shoppingBudget} onChange={(e) => { setBudget({ ...budget, shoppingBudget: Number(e.target.value) }); setNotice('Saved locally'); }} /></label>{notice && <p className="mt-3 text-xs font-semibold text-primary"><Check size={13} className="mr-1 inline" /> {notice}</p>}</div><div className="surface rounded-2xl p-6"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-accent/15 text-[#b84b3c]"><RotateCcw size={18} /></div><div><h2 className="font-display text-xl font-bold">Reset demonstration data</h2><p className="text-xs text-muted-foreground">Useful before a fresh testing session.</p></div></div><p className="mt-5 text-sm leading-6 text-muted-foreground">This clears your local changes and restores the labelled sample workspace. Tester feedback is also cleared, never replaced with made-up results.</p><Button variant="danger" className="mt-5" onClick={() => { if (window.confirm('Reset all local prototype data?')) onReset(); }}><Trash2 size={15} /> Reset local data</Button></div></div><div className="surface rounded-2xl p-6"><div className="flex items-center gap-3"><Bell size={18} className="text-primary" /><h2 className="font-display text-xl font-bold">Prototype commitments</h2></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><div><div className="font-semibold text-sm">Local-first</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Your entries stay in this browser via localStorage.</p></div><div><div className="font-semibold text-sm">Transparent</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Sample data, price rows, and rule-based guidance are labelled.</p></div><div><div className="font-semibold text-sm">Accessible</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Keyboard-friendly controls, focus states, and meaningful empty states.</p></div></div></div></div>;
}

function Shell() {
  const [location, setLocation] = useLocation();
  const [budget, setBudget] = useStored<BudgetSettings>('smart-budget-budget', initialBudget);
  const [items, setItems] = useStored<ShoppingItem[]>('smart-budget-items', initialItems);
  const [goals, setGoals] = useStored<SavingsGoal[]>('smart-budget-goals', initialGoals);
  const [feedback, setFeedback] = useStored<ValidationFeedback[]>('smart-budget-feedback', []);
  const [iterationRecords, setIterationRecords] = useStored<IterationRecord[]>('smart-budget-iterations', []);
  const [aiEntries, setAiEntries] = useStored<AIAuditEntry[]>('smart-budget-ai-audit', []);
 const currentPath = location === '' || location === '/smart-budget-shopping-assistant-review-2/' ? '/' : location.replace('/smart-budget-shopping-assistant-review-2', '') || '/';
  const currentLabel = allNav.find(([path]) => path === currentPath)?.[1] || 'Dashboard';
  const navigate = (path: string) => setLocation(path);
  const reset = () => { setBudget(initialBudget); setItems(initialItems); setGoals(initialGoals); setFeedback([]); setIterationRecords([]); setAiEntries([]); navigate('/'); };
  const loadDemo = () => { setBudget(initialBudget); setItems(initialItems); setGoals(initialGoals); navigate('/'); };
  const content = useMemo(() => {
    if (currentPath === '/') return <Dashboard budget={budget} items={items} goals={goals} onNavigate={navigate} onLoadDemo={loadDemo} onReset={reset} />;
    if (currentPath === '/shopping-list') return <EnhancedShoppingList items={items} setItems={setItems} />;
    if (currentPath === '/budget-planner') return <BudgetPlanner budget={budget} setBudget={setBudget} items={items} />;
    if (currentPath === '/need-vs-want') return <NeedWant items={items} onNavigate={navigate} />;
    if (currentPath === '/price-comparison') return <PriceComparison items={items} />;
    if (currentPath === '/recommendations') return <Recommendations items={items} budget={budget} onNavigate={navigate} />;
    if (currentPath === '/what-if') return <WhatIf items={items} budget={budget} />;
    if (currentPath === '/analytics') return <Analytics items={items} budget={budget} />;
    if (currentPath === '/savings-goals') return <EnhancedSavingsGoals goals={goals} setGoals={setGoals} />;
    if (currentPath === '/ask-smartbudget') return <AskSmartBudget />;
    if (currentPath === '/prototype-validation') return <PrototypeValidation feedback={feedback} setFeedback={setFeedback} />;
    if (currentPath === '/feedback-iteration') return <IterationTracker records={iterationRecords} setRecords={setIterationRecords} />;
    if (currentPath === '/ai-audit') return <AIAudit entries={aiEntries} setEntries={setAiEntries} />;
    if (currentPath === '/design-thinking') return <DesignJourney feedbackCount={feedback.length} />;
    if (currentPath === '/settings') return <Settings budget={budget} setBudget={setBudget} onReset={reset} />;
    if (['/feedback-iteration', '/design-thinking', '/ai-audit', '/review-2-evidence', '/project-evolution'].includes(currentPath)) return <EvidencePages page={currentPath} feedback={feedback} />;
    return <div className="surface rounded-2xl p-10 text-center"><div className="font-display text-2xl font-bold">This view is not in the map yet</div><p className="mt-2 text-sm text-muted-foreground">Choose another workspace view.</p><Button className="mt-5" onClick={() => navigate('/')}>Back to dashboard</Button></div>;
  }, [aiEntries, budget, currentPath, feedback, goals, iterationRecords, items, navigate, setBudget, setFeedback, setGoals, setItems, setIterationRecords, setAiEntries]);
  return <div className="min-h-[100dvh] bg-background"><aside className="fixed inset-y-0 left-0 z-30 hidden w-[252px] flex-col border-r border-border bg-[#f4efdf] px-4 py-5 md:flex"><Logo /><div className="mt-8 flex-1 overflow-y-auto pr-1">{navGroups.map((group) => <div key={group.label} className="mb-6"><div className="eyebrow mb-2 px-3">{group.label}</div><div className="space-y-1">{group.items.map(([path, label, Icon]) => <button key={path} onClick={() => navigate(path as string)} data-testid={`nav-${String(label).toLowerCase().replaceAll(' ', '-')}`} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[13px] font-semibold transition ${currentPath === path ? 'bg-primary text-primary-foreground shadow-sm' : 'text-foreground/70 hover:bg-background hover:text-foreground'}`}><Icon size={16} />{label as string}{currentPath === path && <ArrowRight size={14} className="ml-auto opacity-70" />}</button>)}</div></div>)}</div><div className="border-t border-border pt-4"><button onClick={() => navigate('/settings')} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${currentPath === '/settings' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-background'}`}><Settings2 size={16} />Settings</button><div className="mt-4 flex items-center gap-2 px-2"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e8806d] text-xs font-bold text-[#fff7ea]">BT</div><div><div className="text-xs font-semibold">Better Tomorrow</div><div className="font-mono text-[9px] text-muted-foreground">LOCAL PROTOTYPE</div></div></div></div></aside><main className="md:pl-[252px]"><header className="sticky top-0 z-20 border-b border-border bg-background/90 px-4 py-3 backdrop-blur-md sm:px-7 md:px-9"><div className="flex items-center justify-between gap-4"><div className="flex items-center gap-3 md:hidden"><Logo /></div><div className="hidden items-center gap-2 text-sm text-muted-foreground md:flex"><span className="font-mono text-[10px] uppercase tracking-[.13em]">Workspace</span><ChevronDown size={14} /><span className="font-semibold text-foreground">{currentLabel}</span></div><div className="ml-auto flex items-center gap-2"><Tag tone="gold"><span className="hidden sm:inline">Pathway A – Continuation Track</span><span className="sm:hidden">Pathway A</span></Tag><div className="hidden h-8 w-px bg-border sm:block" /><button onClick={() => navigate('/settings')} className="grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted" aria-label="Open settings"><UserRound size={17} /></button></div></div><select value={currentPath} onChange={(e) => navigate(e.target.value)} className="mt-3 block w-full md:hidden" aria-label="Navigate workspace">{allNav.map(([path, label]) => <option key={path} value={path as string}>{label as string}</option>)}<option value="/settings">Settings</option></select></header><div className="mx-auto max-w-[1480px] px-4 py-7 sm:px-7 md:px-9 md:py-9"><div className="mb-7 hidden items-center justify-between md:flex"><div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 rounded-full bg-primary" /> Everything is saved in this browser</div><div className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">SMART BUDGET SHOPPING ASSISTANT · REVIEW 2</div></div>{content}</div></main></div>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary><Shell /></ErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;
